CREATE EXTENSION vector;
SELECT setseed(0.25);
CREATE TABLE puntos (id int PRIMARY KEY, grupo int NOT NULL, v vector(8));
INSERT INTO puntos
SELECT i, i % 20, ARRAY[random(), random(), random(), random(), random(), random(), random(), random()]::vector(8)
FROM generate_series(1, 5000) AS i;
CREATE INDEX puntos_hnsw ON puntos USING hnsw (v vector_l2_ops) WITH (m = 16, ef_construction = 64);
ANALYZE puntos;
\set q '[0.5,0.5,0.5,0.5,0.5,0.5,0.5,0.5]'
SET enable_seqscan = off;
EXPLAIN (COSTS OFF) SELECT id FROM puntos WHERE grupo = 7 ORDER BY v <-> :'q' LIMIT 10;
-- 1) Con el índice y el filtro: ¿cuántas filas vuelven?
SELECT id, round((v <-> :'q')::numeric, 4) AS dist FROM puntos WHERE grupo = 7 ORDER BY v <-> :'q' LIMIT 10;
-- 2) Búsqueda iterativa (pgvector 0.8): sigue buscando hasta llenar el LIMIT
SET hnsw.iterative_scan = relaxed_order;
SELECT id, round((v <-> :'q')::numeric, 4) AS dist FROM puntos WHERE grupo = 7 ORDER BY v <-> :'q' LIMIT 10;
SET hnsw.iterative_scan = strict_order;
SELECT id, round((v <-> :'q')::numeric, 4) AS dist FROM puntos WHERE grupo = 7 ORDER BY v <-> :'q' LIMIT 10;
-- 3) La verdad: búsqueda exacta, sin índice
RESET hnsw.iterative_scan;
SET enable_seqscan = on;
SET enable_indexscan = off;
SELECT id, round((v <-> :'q')::numeric, 4) AS dist FROM puntos WHERE grupo = 7 ORDER BY v <-> :'q' LIMIT 10;

CREATE EXTENSION vector;
SELECT setseed(0.25);
CREATE TABLE puntos (id int PRIMARY KEY, v vector(8));
INSERT INTO puntos
SELECT i, ARRAY[random(), random(), random(), random(), random(), random(), random(), random()]::vector(8)
FROM generate_series(1, 5000) AS i;
-- La verdad: los 10 vecinos exactos de los puntos 1 a 20 (todavía no hay índice)
CREATE TABLE exactos AS
SELECT q.id AS consulta, v.id
FROM generate_series(1, 20) AS q (id)
CROSS JOIN LATERAL (SELECT p.id FROM puntos AS p
                    ORDER BY p.v <-> (SELECT v FROM puntos WHERE id = q.id) LIMIT 10) AS v;
CREATE INDEX puntos_ivf ON puntos USING ivfflat (v vector_l2_ops) WITH (lists = 50);
ANALYZE puntos;
-- Cuántos de los 10 vecinos exactos encuentra el índice, en promedio
CREATE VIEW aciertos AS
SELECT round(count(*) / 20.0, 1) AS aciertos_de_10
FROM generate_series(1, 20) AS q (id)
CROSS JOIN LATERAL (SELECT p.id FROM puntos AS p
                    ORDER BY p.v <-> (SELECT v FROM puntos WHERE id = q.id) LIMIT 10) AS a
JOIN exactos AS e ON e.consulta = q.id AND e.id = a.id;
SET ivfflat.probes = 1;
SELECT * FROM aciertos;
SET ivfflat.probes = 7;
SELECT * FROM aciertos;
SET ivfflat.probes = 50;
SELECT * FROM aciertos;
EXPLAIN (COSTS OFF) SELECT p.id FROM puntos AS p ORDER BY p.v <-> (SELECT v FROM puntos WHERE id = 3) LIMIT 10;

