CREATE EXTENSION postgis;
CREATE TABLE ciudades (nombre text PRIMARY KEY, ubicacion geography(Point, 4326) NOT NULL);
INSERT INTO ciudades VALUES
  ('Santiago',   ST_Point(-70.6504, -33.4378, 4326)),
  ('Valparaíso', ST_Point(-71.6283, -33.0386, 4326)),
  ('Concepción', ST_Point(-73.0503, -36.8270, 4326));
SELECT a.nombre AS desde, b.nombre AS hasta,
       round(ST_Distance(a.ubicacion, b.ubicacion)::numeric / 1000, 1) AS km
FROM ciudades AS a JOIN ciudades AS b ON a.nombre < b.nombre
ORDER BY km;
-- Lo mismo con geometry: ¡el resultado está en grados!
SELECT round(ST_Distance(a.ubicacion::geometry, b.ubicacion::geometry)::numeric, 4) AS grados
FROM ciudades AS a, ciudades AS b
WHERE a.nombre = 'Santiago' AND b.nombre = 'Valparaíso';
-- Esferoide (por defecto) vs. esfera
SELECT round(ST_Distance(a.ubicacion, b.ubicacion)::numeric / 1000, 1) AS esferoide_km,
       round(ST_Distance(a.ubicacion, b.ubicacion, false)::numeric / 1000, 1) AS esfera_km
FROM ciudades AS a, ciudades AS b
WHERE a.nombre = 'Santiago' AND b.nombre = 'Concepción';

