       round((earth_distance(ll_to_earth(-33.4378, -70.6504), ll_to_earth(-36.8270, -73.0503)) / 1000)::numeric, 1) AS santiago_concepcion_km;
-- El operador <@> recibe point(longitud, latitud) y responde en millas terrestres
