       round((ubicacion <-> ST_Point(-70.6504, -33.4378, 4326)::geography)::numeric) AS knn_esfera,
       round(ST_Distance(ubicacion, ST_Point(-70.6504, -33.4378, 4326)::geography)::numeric) AS distancia
