CREATE EXTENSION earthdistance CASCADE;
CREATE INDEX estaciones_tierra ON estaciones USING gist (ll_to_earth(lat, lon));
-- 1) Solo la caja (rápida, con índice): incluye las «esquinas»
SELECT nombre, round(earth_distance(ll_to_earth(lat, lon), ll_to_earth(-33.4378, -70.6504))::numeric, 1) AS metros
FROM estaciones
WHERE earth_box(ll_to_earth(-33.4378, -70.6504), 1000) @> ll_to_earth(lat, lon)
ORDER BY metros;
-- 2) Caja + distancia exacta: la respuesta correcta
SELECT nombre, round(earth_distance(ll_to_earth(lat, lon), ll_to_earth(-33.4378, -70.6504))::numeric, 1) AS metros
FROM estaciones
WHERE earth_box(ll_to_earth(-33.4378, -70.6504), 1000) @> ll_to_earth(lat, lon)
  AND earth_distance(ll_to_earth(lat, lon), ll_to_earth(-33.4378, -70.6504)) <= 1000
ORDER BY metros;
SET enable_seqscan = off;
EXPLAIN (COSTS OFF)
SELECT nombre FROM estaciones
WHERE earth_box(ll_to_earth(-33.4378, -70.6504), 1000) @> ll_to_earth(lat, lon);

