-- Literales (16): guiones bajos y bases 16, 8 y 2
SELECT 1_000_000 AS millon, 0x1F AS hexadecimal, 0o17 AS octal, 0b1010 AS binario;
-- any_value (16): «cualquier valor del grupo», sin inventar un max() que no significa nada
