FROM clientes
WHERE region IS NOT NULL
GROUP BY region
ORDER BY clientes DESC
LIMIT 3;
-- SQL/JSON estándar (16): el predicado IS JSON y los constructores
SELECT '{"a": 1}' IS JSON AS valido, '[1, 2' IS JSON AS roto,
       '{"a": 1, "a": 2}' IS JSON WITH UNIQUE KEYS AS claves_unicas;
SELECT JSON_OBJECT('sku': sku, 'precio': precio) AS ficha FROM productos WHERE id = 1;
SELECT JSON_ARRAYAGG(sku ORDER BY sku) AS cafes FROM productos WHERE categoria_id = 13;
-- Validar una entrada sin provocar un error (16)
SELECT pg_input_is_valid('12.5', 'integer') AS es_entero;
SELECT * FROM pg_input_error_info('12.5', 'integer');
-- El plan genérico de una consulta con parámetros, sin darle valores (16)
