-- JSON_TABLE (17): de un documento a filas y columnas tipadas
SELECT *
FROM JSON_TABLE(
  '{"pedido": 421, "items": [{"sku": "CAF-001", "cant": 2}, {"sku": "ALI-002", "cant": 1}]}',
  '$.items[*]'
  COLUMNS (n FOR ORDINALITY, sku text PATH '$.sku', cantidad int PATH '$.cant')
) AS jt;
SELECT JSON_VALUE('{"precio": 19990}', '$.precio' RETURNING int) AS precio,
       JSON_EXISTS('{"tags": ["oferta"]}', '$.tags[0]') AS tiene_tag,
       JSON_QUERY('{"tags": ["oferta", "nuevo"]}', '$.tags') AS tags;
-- MERGE (15) con WHEN NOT MATCHED BY SOURCE y RETURNING (17)
CREATE TABLE lista_cafe AS SELECT sku, precio FROM productos WHERE categoria_id = 13;
CREATE TABLE precios_proveedor (sku text PRIMARY KEY, precio int NOT NULL);
INSERT INTO precios_proveedor VALUES ('CAF-001', 21990), ('CAF-002', 9990), ('CAF-005', 12990);
MERGE INTO lista_cafe AS l
USING precios_proveedor AS n ON n.sku = l.sku
WHEN MATCHED AND l.precio <> n.precio THEN UPDATE SET precio = n.precio
WHEN NOT MATCHED THEN INSERT (sku, precio) VALUES (n.sku, n.precio)
WHEN NOT MATCHED BY SOURCE THEN DELETE
RETURNING merge_action() AS accion, l.sku, old.precio AS antes, new.precio AS despues;

