CREATE FUNCTION buscar_productos(consulta vector, precio_max integer, k integer DEFAULT 5)
RETURNS TABLE (sku text, nombre text, precio integer, similitud numeric)
LANGUAGE sql STABLE
AS $$
  SELECT p.sku, p.nombre, p.precio,
         round((1 - (p.embedding <=> consulta))::numeric, 3)
  FROM productos AS p
  WHERE p.activo AND p.precio <= precio_max
  ORDER BY p.embedding <=> consulta, p.sku
  LIMIT k;
$$;

