CREATE FUNCTION estaciones_cercanas(lon double precision, lat double precision, radio_m double precision DEFAULT 1000)
RETURNS TABLE (estacion text, lineas text, metros integer)
LANGUAGE sql STABLE
AS $$
  SELECT e.nombre,
         (SELECT string_agg(le.linea_id, ', ' ORDER BY le.linea_id)
          FROM linea_estacion AS le WHERE le.estacion_id = e.id),
         round(ST_Distance(e.ubicacion, ST_Point(estaciones_cercanas.lon, estaciones_cercanas.lat, 4326)::geography))::integer AS m
  FROM estaciones AS e
  WHERE ST_DWithin(e.ubicacion, ST_Point(estaciones_cercanas.lon, estaciones_cercanas.lat, 4326)::geography, radio_m)
  ORDER BY m, e.nombre;
$$;

